{inserted, skipped, contribution_rows} =
  Enum.reduce(new_exercises, {0, 0, 0}, fn attrs, {ins, skip, rows} ->
    key = String.downcase(attrs.name)

    if MapSet.member?(existing_names, key) do
      {ins, skip + 1, rows}
    else
      equipment_id = Map.fetch!(equipment, attrs.equipment)
      muscle_id = Map.fetch!(muscles, attrs.muscle)

      exercise =
        %Exercise{}
        |> Exercise.changeset(%{
          name: attrs.name,
          muscle_id: muscle_id,
          equipment_id: equipment_id,
          is_custom: false,
          is_unilateral: attrs.is_unilateral
        })
        |> Repo.insert!()

      row_count =
        Enum.reduce(attrs.contributions, 0, fn contrib, count ->
          case Map.fetch(muscles, contrib.muscle) do
            {:ok, contrib_muscle_id} ->
              %ExerciseMuscleContribution{}
              |> ExerciseMuscleContribution.changeset(%{
                exercise_id: exercise.id,
                muscle_id: contrib_muscle_id,
                role: contrib.role,
                multiplier: contrib.multiplier
              })
              |> Repo.insert!()

              count + 1

            :error ->
              count
          end
        end)

      {ins + 1, skip, rows + row_count}
    end
  end)

IO.puts("Inserted #{inserted} exercises (#{contribution_rows} muscle contribution rows).")
IO.puts("Skipped #{skipped} exercises that already existed by name.")
